// @ts-nocheck

/**
 * SigUI CLI generators module for bundle.
 * @module
 */
import * as path from "node:path";
import { Glob } from "bun";
import { generateTokenCSS } from "./css.js";
/** @typedef {import("@sig-ui/theme").SiguiConfig} SiguiConfig */
/**
 * resolveStylesDir.
 * @returns {string}
 */
export function resolveStylesDir() {
  try {
    const pkgJson = import.meta.resolve("@sig-ui/components/package.json");
    const pkgPath = pkgJson.startsWith("file://") ? new URL(pkgJson).pathname : pkgJson;
    const dir = path.dirname(pkgPath);
    return path.join(dir, "src", "styles");
  } catch {
    return path.resolve(import.meta.dir, "../../../components/src/styles");
  }
}
async function readComponentCSS(options) {
  const stylesDir = resolveStylesDir();
  const componentsDir = path.join(stylesDir, "..", "components");
  const glob = new Glob("**/*.css");
  const componentFiles = [];
  for await (const file of glob.scan({ cwd: componentsDir, absolute: true })) {
    componentFiles.push(file);
  }
  componentFiles.sort();
  const componentContents = await Promise.all(componentFiles.map((f) => Bun.file(f).text()));
  const [sharedKeyframes, sharedStates, globals, utilities, animations, shield] = await Promise.all([
    Bun.file(path.join(stylesDir, "shared-keyframes.css")).text(),
    Bun.file(path.join(stylesDir, "shared-states.css")).text(),
    Bun.file(path.join(stylesDir, "globals.css")).text(),
    options?.utilities !== false ? Bun.file(path.join(stylesDir, "utilities.css")).text() : Promise.resolve(""),
    Bun.file(path.join(stylesDir, "animations.css")).text(),
    Bun.file(path.join(stylesDir, "shield.css")).text()
  ]);
  const componentStyles = [
    ...componentContents,
    sharedKeyframes,
    sharedStates,
    globals
  ].join(`
`);
  return { componentStyles, utilities, animations, shield };
}
const RESET_CSS = `@layer sigui.reset {
  *, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }
}`;
/**
 * generateBundleCSS.
 * @param {SiguiConfig} config
 * @returns {Promise<string>}
 */
export async function generateBundleCSS(config) {
  const tokenCSS = generateTokenCSS(config);
  const includeUtilities = config.utilities !== false;
  const components = await readComponentCSS({ utilities: includeUtilities });
  const layers = includeUtilities ? "sigui.reset, sigui.tokens, sigui.base, sigui.variants, sigui.states, sigui.utilities, sigui.overrides" : "sigui.reset, sigui.tokens, sigui.base, sigui.variants, sigui.states, sigui.overrides";
  const parts = [
    "/* Generated by @sig-ui/cli - do not edit */",
    `@layer ${layers};`,
    "",
    RESET_CSS,
    "",
    tokenCSS,
    components.componentStyles,
    ""
  ];
  if (components.utilities) {
    parts.push(components.utilities);
    parts.push("");
  }
  if (components.animations) {
    parts.push(components.animations);
    parts.push("");
  }
  parts.push(components.shield);
  parts.push("");
  return parts.join(`
`);
}
